fn is_prime(n: i8) -> bool {
    // Check if n is less than 2, in which case it is not prime
    if n < 2 {
        return false;
    }

    // Iterate through potential divisors from 2 to n - 1
    for k in 2..n {
        // If n is divisible by k, it is not prime
        if n % k == 0 {
            return false;
        }
    }

    // If no divisors were found, n is prime
    true
}